 if(request.method==="GET"&&p==="/editor-app.js")return new Response(EDITOR_CLIENT,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"public,max-age=300","x-content-type-options":"nosniff"}});
 if(request.method==="GET"&&p==="/api/health")return json({ok:true,app:"ai-toolbox",version:"0.8.2",tools:TOOLS.length,ready:TOOLS.filter(x=>["ready","text-ready","batch-ready"].includes(x.status)).length+(providerStatus(env).imageConfigured?1:0),batchReady:2,aiTextReady:TOOLS.filter(x=>x.status==="text-ready").length,cloud:"cloudflare-workers"});
